mapper.select:
select us.user_id, us.dept_id, us.is_default, us.create_by, us.create_time from sys_user_shop us inner join sys_dept d on d.dept_id = us.dept_id where us.user_id in
#{userId}
and d.del_flag = '0' and d.status = '0' and d.dept_type in ('GROUP', 'COMPANY', 'STORE', 'WAREHOUSE') order by us.user_id, d.parent_id, d.order_num

mapper.delete:
delete from sys_user_shop
where user_id = #{userId}


        and dept_id in

            #{deptId}



        and 1 = 0

mapper.insert:
insert into sys_user_shop (user_id, dept_id, is_default, create_by, create_time)
select #{userId}, #{deptId}, 'N', #{operator}, sysdate() from dual
where not exists (
    select 1 from sys_user_shop where user_id = #{userId} and dept_id = #{deptId}
)
